// ratelimit/ratelimit.go
package ratelimit

import (
	"errors"
	"math"
	"sync"
	"time"
)

// Clock abstracts time so tests can drive it deterministically.
type Clock interface {
	Now() time.Time
}

// RealClock returns the system clock.
type RealClock struct{}

func (RealClock) Now() time.Time { return time.Now() }

// Bucket is a concurrency-safe token-bucket rate limiter.
//
// The bucket holds at most capacity tokens. Tokens are refilled at rate
// tokens per second, up to capacity. AllowN consumes n tokens if and only if
// n tokens are currently available; otherwise it returns false and consumes
// nothing.
type Bucket struct {
	mu       sync.Mutex
	clock    Clock
	capacity float64
	rate     float64
	tokens   float64
	last     time.Time
}

// NewBucket validates and returns a Bucket.
//
// capacity must be finite and > 0. rate must be finite and > 0. clock may be
// nil, in which case RealClock is used.
func NewBucket(capacity float64, rate float64, clock Clock) (*Bucket, error) {
	if math.IsNaN(capacity) || math.IsInf(capacity, 0) || capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be finite and > 0")
	}
	if math.IsNaN(rate) || math.IsInf(rate, 0) || rate <= 0 {
		return nil, errors.New("ratelimit: rate must be finite and > 0")
	}
	if clock == nil {
		clock = RealClock{}
	}
	now := clock.Now()
	return &Bucket{
		clock:    clock,
		capacity: capacity,
		rate:     rate,
		tokens:   capacity,
		last:     now,
	}, nil
}

// AllowN reports whether n tokens can be consumed at the current instant.
// It is safe for concurrent use.
func (b *Bucket) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	b.mu.Lock()
	defer b.mu.Unlock()

	now := b.clock.Now()
	b.tokens = b.refillLocked(now)
	if float64(n) <= b.tokens {
		b.tokens -= float64(n)
		return true
	}
	return false
}

// refillLocked advances the bucket to now and returns the available tokens.
// Callers must hold b.mu.
func (b *Bucket) refillLocked(now time.Time) float64 {
	elapsed := now.Sub(b.last)
	if elapsed > 0 {
		b.tokens += float64(elapsed) * (b.rate / float64(time.Second))
		if b.tokens > b.capacity {
			b.tokens = b.capacity
		}
		b.last = now
	}
	return b.tokens
}
