package ratelimit

import (
	"errors"
	"math"
	"sync"
	"time"
)

// Clock abstracts time.Now so tests can drive the limiter deterministically.
type Clock interface {
	Now() time.Time
}

// RealClock returns the system clock.
type RealClock struct{}

func (RealClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu       sync.Mutex
	clock    Clock
	rate     float64 // tokens per second
	capacity float64 // max tokens
	tokens   float64
	last     time.Time
}

// New validates parameters and returns a fully refilled Limiter.
func New(clock Clock, rate, capacity float64) (*Limiter, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: nil clock")
	}
	if math.IsNaN(rate) || math.IsInf(rate, 0) || rate <= 0 {
		return nil, errors.New("ratelimit: rate must be a positive finite number")
	}
	if math.IsNaN(capacity) || math.IsInf(capacity, 0) || capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be a positive finite number")
	}
	now := clock.Now()
	return &Limiter{
		clock:    clock,
		rate:     rate,
		capacity: capacity,
		tokens:   capacity,
		last:     now,
	}, nil
}

// AllowN reports whether n tokens may be consumed at the current instant.
// It never blocks; on failure it consumes nothing.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last)
	if elapsed > 0 {
		l.tokens += elapsed.Seconds() * l.rate
		if l.tokens > l.capacity {
			l.tokens = l.capacity
		}
		l.last = now
	}

	need := float64(n)
	if l.tokens < need {
		return false
	}
	l.tokens -= need
	return true
}
